import {makeQuestion,editorialDifficulty} from './catalog.js';
export const structure=[];
let skill='structure-core';
function g(sentence,answer,wrong,why,focus=''){
 const n=structure.length+1;const split=n<=10?'diagnostic':n<=200?'practice':'final';
 structure.push(makeQuestion(`S${String(n).padStart(3,'0')}`,'structure',skill,split,'Choose the option that best completes the sentence.',[answer,why],wrong.map(([text,reason])=>[text,reason]),sentence.replace('____',answer),why,{sentence,annotations:focus?[{text:focus,role:'Bagian yang perlu diperhatikan'}]:[],kind:'completion'}));
}
function e(sentence,parts,bad,why,reasons){
 const n=structure.length+1;const split=n<=10?'diagnostic':n<=200?'practice':'final';
 structure.push({id:`S${String(n).padStart(3,'0')}`,section:'structure',skill:'structure-error',split,difficulty:editorialDifficulty('structure','structure-error',split,sentence),prompt:'Choose the marked part that must be changed for the sentence to be correct.',sentence,options:parts,answer:bad,rationales:reasons.map((r,i)=>i===bad?why:r),explanation:why,evidence:sentence,lesson:'structure-error',stimulus:null,kind:'error',annotations:parts.map((text,i)=>({text,role:String.fromCharCode(65+i)})),source:'Naskah orisinal proyek Ruang TOEFL, 2026',permission:'original-project-content',reviewStatus:'editorial-draft',label:'Latihan orisinal bergaya TOEFL ITP'});
}
